sql_query:
SELECT "Type of combination"
FROM clinical_trials
WHERE LOWER(TRIM(COALESCE("Type of combination", ''))) NOT IN ('', 'none', 'null', 'nan') AND TRIM(COALESCE("Cancer type", '')) = 'Head and Neck' AND TRIM(COALESCE("Included in MA", '')) = 'Yes' AND TRIM(COALESCE("Monotherapy/combination", '')) = 'Combination' AND TRIM(COALESCE("Trial phase", '')) = 'Phase 3';

ground_truth_sql:
WITH base AS (
SELECT "NCT", "PubMed ID", "Trial name", "Type of combination" AS source_value FROM clinical_trials WHERE LOWER(TRIM(COALESCE("Type of combination", ''))) NOT IN ('', 'none', 'null', 'nan') AND TRIM(COALESCE("Cancer type", '')) = 'Head and Neck' AND TRIM(COALESCE("Included in MA", '')) = 'Yes' AND TRIM(COALESCE("Monotherapy/combination", '')) = 'Combination' AND TRIM(COALESCE("Trial phase", '')) = 'Phase 3'
)
SELECT "NCT", "PubMed ID", "Trial name", source_value, derive_combo_type_norm(source_value) AS "combo_type_norm"
FROM base;
